class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        stack=[]
        for token in tokens:
            if token not in {'+','-','*','/'}:stack.append(int(token));continue
            b=stack.pop();a=stack.pop()
            if token=='+':v=a+b
            elif token=='-':v=a-b
            elif token=='*':v=a*b
            else:v=(abs(a)//abs(b))*(-1 if (a<0)!=(b<0) else 1)
            stack.append(v)
        return stack[-1]

import java.util.*;

class Solution {
    public int evalRPN(String[] tokens){Deque<Integer>st=new ArrayDeque<>();for(String t:tokens){if(!t.equals("+")&&!t.equals("-")&&!t.equals("*")&&!t.equals("/")){st.push(Integer.parseInt(t));continue;}int b=st.pop(),a=st.pop();switch(t){case "+":st.push(a+b);break;case "-":st.push(a-b);break;case "*":st.push(a*b);break;default:st.push(a/b);}}return st.pop();}
}

